import { trollKinds, trollZoomCueLabel } from "@26/shared";
import type { RoomPhase } from "../room/lifecycle.ts";

export const implementedTrollKinds = trollKinds;

/**
 * The theme song jingle, generated by `scripts/generate-theme-sting.mjs`.
 * Replace the file at `apps/web/public/assets/demo-sting.wav` with any short PCM WAV.
 */
export const demoStingAsset = "/assets/demo-sting.wav";

export const themeCueCap = 4;

/** The stage zooms slowly into a cue photo with this asset label. */
export const zoomAssetLabel = trollZoomCueLabel;
export const draftGapMs = 200;

export type TrollKind = (typeof implementedTrollKinds)[number];

export const modifierOrder = ["double"] as const;

/**
 * Score modifiers a question can opt into with `modifiers`. `double` changes
 * one player's own award. The rest move points between players after every
 * award is known, in `transferOrder`.
 */
export const scoreModifiers = ["double", "steal", "robin-hood", "share"] as const;
export type ScoreModifier = (typeof scoreModifiers)[number];
export const transferOrder = ["steal", "robin-hood", "share"] as const;

export type TrollDefinition = {
  kind: TrollKind;
  label: string;
  assetLabel: string;
  slot: "transient" | "persistent";
  durationMs: number | null;
  phases: readonly RoomPhase[];
  escape: string | null;
  disruptsSubmission: boolean;
  /** `now` captions immediately. `reveal` and `scores` wait for that phase. */
  announce: "now" | "reveal" | "scores";
  /** Persistent effects usually end with the question. A theme song continues. */
  survivesQuestions: boolean;
  cueMs: number;
  /** Only offered on these question kinds, because it does nothing elsewhere. */
  questionKinds?: readonly string[];
  /** A score modifier: only offered when the question lists it in `modifiers`. */
  modifier?: boolean;
};

const immediate = {
  announce: "now" as const,
  survivesQuestions: false,
  cueMs: 4_000,
};

