/**
 * A points-moving troll. It only runs on a choice question that lists its kind
 * in `modifiers`, lasts the question, and settles at the reveal.
 */
function scoring(kind: TrollKind, label: string, assetLabel: string): TrollDefinition {
  return {
    ...screenTroll(kind, label, assetLabel, null),
    slot: "persistent",
    phases: ["collect", "vote", "predict"],
    questionKinds: ["choice"],
    modifier: true,
  };
}

/**
 * Input sabotage: messes with the answer controls while the target answers.
 * It counts as disrupting a submission, so a question that suppresses speed
 * points does so while it runs.
 */
function sabotage(
  kind: TrollKind,
  label: string,
  assetLabel: string,
  durationMs: number,
  questionKinds: readonly string[],
): TrollDefinition {
  return {
    ...screenTroll(kind, label, assetLabel, durationMs),
    phases: ["collect", "vote", "predict"],
    disruptsSubmission: true,
    questionKinds,
  };
}

/**
 * A phone-only gag. The phone draws it and the target can keep playing
 * underneath unless the overlay covers the screen. `escape` is the in-overlay
 * challenge that clears it early.
 */
function screenTroll(
  kind: TrollKind,
  label: string,
  assetLabel: string,
  durationMs: number | null,
  escape: string | null = null,
): TrollDefinition {
  return {
    kind,
    label,
    assetLabel,
    slot: "transient",
    durationMs,
    phases: ["prompt", "collect", "vote", "predict", "reveal"],
    escape,
    disruptsSubmission: false,
    ...immediate,
  };
}

export function isTrollKind(value: unknown): value is TrollKind {
  return implementedTrollKinds.some((kind) => kind === value);
}

export function slotDecision(input: {
  active: boolean;
  queued: boolean;
}): "start" | "queue" | "occupied" {
  if (!input.active) {
    return "start";
  }
  if (!input.queued) {
    return "queue";
  }
  return "occupied";
}

/**
 * A refund returns the one token only when the effect never started and has
 * not already been refunded. A later spend stays spent.
 */
export function nextTokenState(input: {
  token: "ready" | "spent";
  effectRefunded: boolean;
  started: boolean;
}): { token: "ready" | "spent"; refunded: boolean } {
  if (input.effectRefunded || input.started) {
    return { token: input.token, refunded: input.effectRefunded };
  }
  return { token: "ready", refunded: true };
}

/**
 * Modifiers run in `modifierOrder`. A modifier applies only when the question
 * lists it and an accepted effect of that kind is still active. Zero stays zero.
 */
export function applyScoreModifiers(
  points: number,
  detail: string,
  enabled: readonly string[],
  active: readonly string[],
): { points: number; detail: string } {
  let next = points;
  let text = detail;
  for (const name of modifierOrder) {
    if (!enabled.includes(name) || !active.includes(name)) {
      continue;
    }
    if (name === "double") {
      if (next > 0) {
        next *= 2;
        text = `${text}*double`;
      } else {
        text = `${text}*nothing`;
      }
    }
  }
  return { points: next, detail: text };
}

export type PointTransfer = {
  kind: (typeof transferOrder)[number];
  actorId: string;
  targetId: string;
};

/**
 * Moves points between players after every award for a question is known.
 * Runs in `transferOrder` so the result never depends on send order:
 * - steal: the actor takes half (rounded down) of the target's positive award;
 * - robin-hood: the target's positive award goes to `lastPlaceId` (the guest
 *   in last place before this question, never the target);
 * - share: actor and target split their combined award, the odd point to the target.
 * Nothing goes below zero, and points are only moved, never created.
 */
export function applyPointTransfers(
  awards: ReadonlyMap<string, { points: number; detail: string }>,
  transfers: readonly PointTransfer[],
  lastPlaceId: (excludeId: string) => string | null,
): Map<string, { points: number; detail: string }> {
  const result = new Map([...awards].map(([id, award]) => [id, { ...award }]));
  const ensure = (id: string) => {
    const existing = result.get(id);
    if (existing) return existing;
    const created = { points: 0, detail: "none" };
    result.set(id, created);
    return created;
  };
  for (const kind of transferOrder) {
    for (const transfer of transfers.filter((item) => item.kind === kind)) {
      const target = ensure(transfer.targetId);
      if (kind === "steal") {
        const moved = Math.floor(Math.max(0, target.points) / 2);
        if (moved === 0) continue;
        const actor = ensure(transfer.actorId);
        target.points -= moved;
        target.detail += "*stolen";
        actor.points += moved;
        actor.detail += "*stole";
      } else if (kind === "robin-hood") {
        const recipientId = lastPlaceId(transfer.targetId);
        const moved = Math.max(0, target.points);
        if (!recipientId || moved === 0) continue;
        const recipient = ensure(recipientId);
        target.points -= moved;
        target.detail += "*robbed";
        recipient.points += moved;
        recipient.detail += "*robin-hood";
      } else {
        const actor = ensure(transfer.actorId);
        const total = Math.max(0, actor.points) + Math.max(0, target.points);
        actor.points = Math.floor(total / 2);
        target.points = total - actor.points;
        actor.detail += "*shared";
        target.detail += "*shared";
      }
    }
  }
  return result;
}